<script>
window.AkStore={storageKey(s){return`akwad_store_cart_${s}`},readCart(s){try{return JSON.parse(localStorage.getItem(this.storageKey(s))||'[]')}catch{return[]}},writeCart(s,c){localStorage.setItem(this.storageKey(s),JSON.stringify(c));window.dispatchEvent(new CustomEvent('ak-store-cart-updated'))},readWishlist(s){try{return JSON.parse(localStorage.getItem(`akwad_store_wish_${s}`)||'[]')}catch{return[]}},toggleWishlist(s,id){const l=this.readWishlist(s);const i=l.indexOf(id);if(i>=0)l.splice(i,1);else l.push(id);localStorage.setItem(`akwad_store_wish_${s}`,JSON.stringify(l));window.dispatchEvent(new CustomEvent('ak-store-wish-updated'));return l.includes(id)},isWishlisted(s,id){return this.readWishlist(s).includes(id)},addToCart(s,p,q=1){const c=this.readCart(s);const e=c.find(l=>l.id===p.id);if(e)e.quantity=Number(e.quantity)+q;else c.push({id:p.id,name:p.name,sale_price:p.sale_price,vat_percent:p.vat_percent||0,image_url:p.image_url||null,quantity:q});this.writeCart(s,c)},cartCount(s){return this.readCart(s).reduce((a,l)=>a+Number(l.quantity||0),0)},formatMoney(c,a){return`${c} ${Number(a||0).toFixed(2)}`},async fetchQuote(b,l,cc=null){const r=await fetch(`${b}/quote`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({lines:l,coupon_code:cc})});const d=await r.json();if(!r.ok)throw new Error(d.message||'خطأ');return d}};
</script>
